'use strict';
const{chromium}=require('playwright');const B='https://plan-ex.ru/erpv2/';const ok=(v,m)=>{if(!v)throw Error(m)};
(async()=>{const cs=JSON.parse(Buffer.from(process.env.P12_CREDENTIALS_B64||'','base64').toString('utf8'));const c=cs.find(x=>String(x.role).toUpperCase()==='OWNER');ok(c,'OWNER credentials');const b=await chromium.launch({headless:true});const x=await b.newContext({viewport:{width:1920,height:1080},locale:'ru-RU',timezoneId:'Europe/Moscow'});const p=await x.newPage();try{await p.goto(B+'login');await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(c.username);await p.locator('input[type="password"]').fill(c.password);await p.locator('button[type="submit"],input[type="submit"]').first().click();await p.waitForTimeout(700);ok(!p.url().includes('/login'),'login');let r=await p.goto(B+'company/finance/bank-accounts',{waitUntil:'domcontentloaded'});ok(r.status()===200,'bank HTTP');const reg=p.locator('#bank-classification-register');await reg.waitFor({state:'attached',timeout:10000});const h=(await reg.locator('th').allTextContents()).map(s=>s.trim());for(const s of ['ЦФУ','Статья ДДС','Статус'])ok(h.includes(s),'bank header '+s);ok((await reg.innerText()).includes('Разнесение:'),'bank summary');for(const n of ['date_from','date_to','q','classification_status'])ok(await reg.locator(`[name="${n}"]`).count(),'filter '+n);r=await p.goto(B+'company/finance/settings/matching-rules',{waitUntil:'domcontentloaded'});ok(r.status()===200,'rules HTTP');await p.getByText('Справочник ЦФУ',{exact:true}).first().waitFor({state:'visible',timeout:10000});await p.locator('#matching-rule-create-btn').click();await p.waitForTimeout(500);const m=p.locator('#matching-rule-create-modal.is-open');await m.waitFor({state:'attached',timeout:10000});for(const n of ['target_cash_flow_center_id','target_dds_category_id','target_cash_account_id','priority'])ok(await m.locator(`[name="${n}"]`).count(),'field '+n);ok(await m.locator('option[value="transfer_to_cash"]').count(),'bank-to-cash');ok(!/(Fatal error|Parse error|Uncaught TypeError)/i.test(await p.locator('body').innerText()),'fatal');console.log('P41_FINANCE_RUNTIME_OK');}finally{await b.close();}})().catch(e=>{console.error(e);process.exit(1)});
